SELECT DISTINCT ?director ?directorLabel WHERE {
  { dbr:Life_Without_Soul dbo:director ?director } UNION { dbr:Life_Without_Soul dbp:director ?director } .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = 'en') }
}

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  { dbr:Joseph_W._Smiley dbo:deathPlace ?deathPlace } UNION { dbr:Joseph_W._Smiley dbp:deathPlace ?deathPlace } .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER (lang(?deathPlaceLabel) = 'en') }
}

SELECT DISTINCT ?director ?directorLabel ?deathPlaceIRI ?deathPlaceIRIlabel ?deathPlaceLiteral ?deathPlaceMatched WHERE {
  { dbr:Life_Without_Soul dbo:director ?director } UNION { dbr:Life_Without_Soul dbp:director ?director } .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
  OPTIONAL { 
    ?director dbo:deathPlace ?deathPlaceIRI . 
    OPTIONAL { ?deathPlaceIRI rdfs:label ?deathPlaceIRIlabel . FILTER(lang(?deathPlaceIRIlabel) = 'en') }
  }
  OPTIONAL {
    ?director dbp:deathPlace ?deathPlaceLiteral .
    OPTIONAL {
      ?deathPlaceMatched rdfs:label ?deathPlaceMatchedLabel .
      FILTER(lang(?deathPlaceMatchedLabel) = 'en' && lcase(str(?deathPlaceMatchedLabel)) = lcase(str(?deathPlaceLiteral)))
    }
  }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  ?place rdfs:label ?placeLabel .
  FILTER(lang(?placeLabel) = 'en' && lcase(str(?placeLabel)) = 'new york, new york')
} LIMIT 10

